#!/bin/bash

# sync-to-usb-and-cloud.sh
# Syncs (one-way) a local directory to USB drive and encrypted cloud storage
# Designed to be triggered by launchd on USB mount

# TODO: Split this for USB and cloud syncs

set -euo pipefail

# Load configuration from config file generated by install.sh
CONFIG_FILE="${CONFIG_FILE:-${HOME}/.config/securelocal/config.env}"

if [[ ! -f ${CONFIG_FILE} ]]; then
	echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: Configuration file not found: ${CONFIG_FILE}" >&2
	exit 4
fi

# shellcheck source=/dev/null
source "${CONFIG_FILE}"

# Validate required variables
required_vars=(LOCAL_DIR USB_UUID USB_MOUNT_BASE USB_BACKUP_PATH RCLONE_REMOTE LOG_FILE)
for var in "${required_vars[@]}"; do
	if [[ -z ${!var-} ]]; then
		echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: Required configuration variable '${var}' is not set in ${CONFIG_FILE}" >&2
		exit 4
	fi
done

MAX_RETRIES=2

# Logging function
log() {
	echo "[$(date '+%Y-%m-%d %H:%M:%S')] $*" | tee -a "${LOG_FILE}"
}

log_error() {
	echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: $*" | tee -a "${LOG_FILE}" >&2
}

# Find USB drive by UUID
find_usb_by_uuid() {
	for volume in "${USB_MOUNT_BASE}"/*; do
		if [[ -d ${volume} ]]; then
			local vol_uuid
			vol_uuid=$(diskutil info "${volume}" 2>/dev/null | grep "Volume UUID" | awk '{print $3}' || echo "")
			if [[ ${vol_uuid} == "${USB_UUID}" ]]; then
				echo "${volume}"
				return 0
			fi
		fi
	done
	return 1
}

# Sync to USB with retry logic
sync_to_usb() {
	local usb_mount="$1"
	local usb_target="${usb_mount}/${USB_BACKUP_PATH}"
	local attempt=1

	# Create target directory if it doesn't exist
	mkdir -p "${usb_target}"

	while [[ ${attempt} -le ${MAX_RETRIES} ]]; do
		log "USB sync attempt ${attempt} of ${MAX_RETRIES}"

		if rsync -avh --ignore-errors "${LOCAL_DIR}/" "${usb_target}/"; then
			log "USB sync successful"
			return 0
		else
			log_error "USB sync failed on attempt ${attempt}"
			if [[ ${attempt} -lt ${MAX_RETRIES} ]]; then
				log "Waiting 30s before retry..."
				sleep 30
			fi
		fi
		((attempt++))
	done

	return 1
}

# Sync to cloud with retry logic
sync_to_cloud() {
	local attempt=1

	while [[ ${attempt} -le ${MAX_RETRIES} ]]; do
		log "Cloud sync attempt ${attempt} of ${MAX_RETRIES}"

		if rclone sync "${LOCAL_DIR}" "${RCLONE_REMOTE}" \
			--log-file "${LOG_FILE}" \
			--log-level INFO; then
			log "Cloud sync successful"
			return 0
		else
			log_error "Cloud sync failed on attempt ${attempt}"
			if [[ ${attempt} -lt ${MAX_RETRIES} ]]; then
				log "Waiting 30s before retry..."
				sleep 30
			fi
		fi
		((attempt++))
	done

	return 2
}

# Main execution
main() {
	log "=== Sync job started ==="

	# Validate configuration
	if [[ -z ${USB_UUID} ]]; then
		log_error "USB_UUID not configured"
		exit 4
	fi

	if [[ ! -d ${LOCAL_DIR} ]]; then
		log_error "Local directory does not exist: ${LOCAL_DIR}"
		exit 4
	fi

	# Check if rclone is available
	if [[ ! -x "$(command -v rclone)" ]] && ! command -v rclone &>/dev/null; then
		log_error "rclone not found in PATH"
		exit 4
	fi

	# Find USB drive
	log "Looking for USB drive with UUID: ${USB_UUID}"
	if ! usb_mount=$(find_usb_by_uuid); then
		log_error "USB drive not found or not mounted"
		exit 1
	fi

	log "Found USB drive at: ${usb_mount}"

	# Perform syncs
	usb_result=0
	cloud_result=0

	if ! sync_to_usb "${usb_mount}"; then
		usb_result=1
		log_error "USB sync failed after ${MAX_RETRIES} attempts"
	fi

	if ! sync_to_cloud; then
		cloud_result=2
		log_error "Cloud sync failed after ${MAX_RETRIES} attempts"
	fi

	# Determine exit code
	if [[ ${usb_result} -eq 0 ]] && [[ ${cloud_result} -eq 0 ]]; then
		log "=== Sync job completed successfully ==="
		exit 0
	elif [[ ${usb_result} -ne 0 ]] && [[ ${cloud_result} -ne 0 ]]; then
		log_error "=== Both USB and cloud sync failed ==="
		exit 3
	elif [[ ${usb_result} -ne 0 ]]; then
		log_error "=== USB sync failed, cloud sync succeeded ==="
		exit 1
	else
		log_error "=== USB sync succeeded, cloud sync failed ==="
		exit 2
	fi
}

main "$@"
